        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    rays = {}
    for cr, cc, color in centers:
        for c in range(w):
            rays.setdefault((cr, c), set()).add(color)
        for r in range(h):
